dashboard.definition:
{
  "title": "6 · Microsegmentation Change Impact",
  "description": "Tie every connectivity break in VMware NSX back to the rule or port change that caused it.",
  "inputs": {},
  "defaults": {},
  "visualizations": {
    "bg_001": {
      "type": "splunk.rectangle",
      "options": {
        "fillColor": "#161B22",
        "strokeColor": "#262C36",
        "strokeWidth": 1,
        "rx": 12
      }
    },
    "bg_002": {
      "type": "splunk.rectangle",
      "options": {
        "fillColor": "#16A3B0",
        "strokeColor": "#16A3B0",
        "strokeWidth": 1,
        "rx": 3
      }
    },
    "md_003": {
      "type": "splunk.markdown",
      "options": {
        "markdown": "USE CASE 6 OF 9  ·  SPITAL AARWALD  ·  SAMPLE DATA",
        "fontColor": "#16A3B0",
        "fontSize": "custom",
        "customFontSize": 12
      }
    },
    "md_004": {
      "type": "splunk.markdown",
      "options": {
        "markdown": "# Microsegmentation Change Impact — VMware NSX",
        "fontColor": "#E6EDF3"
      }
    },
    "md_005": {
      "type": "splunk.markdown",
      "options": {
        "markdown": "A small rule or port change breaks an app on the other side. Splunk links each break to its change.",
        "fontColor": "#9AA4B2",
        "fontSize": "custom",
        "customFontSize": 15
      }
    },
    "bg_006": {
      "type": "splunk.rectangle",
      "options": {
        "fillColor": "#11161D",
        "strokeColor": "#262C36",
        "strokeWidth": 1,
        "rx": 8
      }
    },
    "md_007": {
      "type": "splunk.markdown",
      "options": {
        "markdown": "WHAT WE HEARD",
        "fontColor": "#6E7681",
        "fontSize": "custom",
        "customFontSize": 11
      }
    },
    "md_008": {
      "type": "splunk.markdown",
      "options": {
        "markdown": "*“Ein kleiner Klick und es tut auf der anderen Seite wieder nichts — dann hat der Lieferant wieder einen Port gewechselt.”*",
        "fontColor": "#9AA4B2",
        "fontSize": "custom",
        "customFontSize": 13
      }
    },
    "bg_009": {
      "type": "splunk.rectangle",
      "options": {
        "fillColor": "#161B22",
        "strokeColor": "#262C36",
        "strokeWidth": 1,
        "rx": 12
      }
    },
    "viz_010": {
      "type": "splunk.singlevalue",
      "options": {
        "backgroundColor": "#161B22",
        "majorColor": "#E6EDF3",
        "numberPrecision": 0,
        "shouldUseThousandSeparators": true,
        "majorFontSize": 42,
        "trendFontSize": 15,
        "trendDisplay": "absolute",
        "sparklineDisplay": "below",
        "showSparklineAreaGraph": true,
        "sparklineStrokeColor": "#16A3B0",
        "sparklineAreaColor": "#16A3B0",
        "underLabel": "rolling 7 days · rules · groups",
        "underLabelColor": "#9AA4B2",
        "underLabelFontSize": 13
      },
      "dataSources": {
        "primary": "ds_011"
      },
      "title": "DFW rule changes (7 days)"
    },
    "bg_012": {
      "type": "splunk.rectangle",
      "options": {
        "fillColor": "#161B22",
        "strokeColor": "#262C36",
        "strokeWidth": 1,
        "rx": 12
      }
    },
    "viz_013": {
      "type": "splunk.singlevalue",
      "options": {
        "backgroundColor": "#161B22",
        "majorColor": "> majorValue | rangeValue(majorColorConfig)",
        "numberPrecision": 0,
        "shouldUseThousandSeparators": true,
        "majorFontSize": 42,
        "trendFontSize": 15,
        "trendDisplay": "absolute",
        "sparklineDisplay": "below",
        "showSparklineAreaGraph": true,
        "sparklineStrokeColor": "#16A3B0",
        "sparklineAreaColor": "#16A3B0",
        "underLabel": "per week",
        "underLabelColor": "#9AA4B2",
        "underLabelFontSize": 13,
        "trendColor": "> trendValue | rangeValue(trendColorConfig)"
      },
      "dataSources": {
        "primary": "ds_014"
      },
      "title": "Changes followed by an outage",
      "context": {
        "trendColorConfig": [
          {
            "to": -0.0001,
            "value": "#0CA30C"
          },
          {
            "from": -0.0001,
            "to": 0.0001,
            "value": "#9AA4B2"
          },
          {
            "from": 0.0001,
            "value": "#D03B3B"
          }
        ],
        "majorColorConfig": [
          {
            "to": 1,
            "value": "#0CA30C"
          },
          {
            "from": 1,
            "value": "#FAB219"
          }
        ]
      }
    },
    "bg_015": {
      "type": "splunk.rectangle",
      "options": {
        "fillColor": "#161B22",
        "strokeColor": "#262C36",
        "strokeWidth": 1,
        "rx": 12
      }
    },
    "viz_016": {
      "type": "splunk.singlevalue",
      "options": {
        "backgroundColor": "#161B22",
        "majorColor": "#E6EDF3",
        "numberPrecision": 0,
        "shouldUseThousandSeparators": true,
        "majorFontSize": 42,
        "trendFontSize": 15,
        "trendDisplay": "absolute",
        "sparklineDisplay": "below",
        "showSparklineAreaGraph": true,
        "sparklineStrokeColor": "#16A3B0",
        "sparklineAreaColor": "#16A3B0",
        "underLabel": "per week · mostly external vendors",
        "underLabelColor": "#9AA4B2",
        "underLabelFontSize": 13,
        "trendColor": "> trendValue | rangeValue(trendColorConfig)"
      },
      "dataSources": {
        "primary": "ds_017"
      },
      "title": "Changes without a ticket",
      "context": {
        "trendColorConfig": [
          {
            "to": -0.0001,
            "value": "#0CA30C"
          },
          {
            "from": -0.0001,
            "to": 0.0001,
            "value": "#9AA4B2"
          },
          {
            "from": 0.0001,
            "value": "#D03B3B"
          }
        ]
      }
    },
    "bg_018": {
      "type": "splunk.rectangle",
      "options": {
        "fillColor": "#161B22",
        "strokeColor": "#262C36",
        "strokeWidth": 1,
        "rx": 12
      }
    },
    "viz_019": {
      "type": "splunk.singlevalue",
      "options": {
        "backgroundColor": "#161B22",
        "majorColor": "#E6EDF3",
        "numberPrecision": 0,
        "shouldUseThousandSeparators": true,
        "majorFontSize": 42,
        "trendFontSize": 15,
        "trendDisplay": "off",
        "sparklineDisplay": "below",
        "showSparklineAreaGraph": true,
        "sparklineStrokeColor": "#16A3B0",
        "sparklineAreaColor": "#16A3B0",
        "unit": " min",
        "unitPosition": "after",
        "underLabel": "was hours of guessing",
        "underLabelColor": "#9AA4B2",
        "underLabelFontSize": 13
      },
      "dataSources": {
        "primary": "ds_020"
      },
      "title": "Time to find the causing change"
    },
    "bg_021": {
      "type": "splunk.rectangle",
      "options": {
        "fillColor": "#161B22",
        "strokeColor": "#262C36",
        "strokeWidth": 1,
        "rx": 12
      }
    },
    "viz_022": {
      "type": "splunk.area",
      "options": {
        "backgroundColor": "#161B22",
        "legendDisplay": "off",
        "xAxisTitleVisibility": "hide",
        "nullValueDisplay": "connect",
        "lineWidth": 2,
        "seriesColors": [
          "#D95926"
        ],
        "yAxisTitleVisibility": "hide"
      },
      "dataSources": {
        "primary": "ds_023"
      },
      "title": "Blocked connections per 5 min — LIS app tier → LIS database (6h)"
    },
    "bg_024": {
      "type": "splunk.rectangle",
      "options": {
        "fillColor": "#161B22",
        "strokeColor": "#262C36",
        "strokeWidth": 1,
        "rx": 12
      }
    },
    "viz_025": {
      "type": "splunk.pie",
      "options": {
        "backgroundColor": "#161B22",
        "showDonutHole": true,
        "labelDisplay": "valuesAndPercentage",
        "legendDisplay": "off",
        "seriesColors": [
          "#3987E5",
          "#D95926",
          "#199E70",
          "#C98500",
          "#D55181",
          "#008300",
          "#9085E9",
          "#E66767"
        ]
      },
      "dataSources": {
        "primary": "ds_026"
      },
      "title": "Who changes NSX rules (30 days)"
    },
    "bg_027": {
      "type": "splunk.rectangle",
      "options": {
        "fillColor": "#161B22",
        "strokeColor": "#262C36",
        "strokeWidth": 1,
        "rx": 12
      }
    },
    "viz_028": {
      "type": "splunk.table",
      "options": {
        "backgroundColor": "#161B22",
        "headerVisibility": "fixed",
        "fontSize": "small",
        "columnFormat": {
          "Impact": {
            "rowBackgroundColors": "> table | seriesByName(\"Impact\") | matchValue(c0Bg)",
            "rowColors": "> table | seriesByName(\"Impact\") | matchValue(c0Fg)"
          },
          "Ticket": {
            "rowBackgroundColors": "> table | seriesByName(\"Ticket\") | matchValue(c2Bg)",
            "rowColors": "> table | seriesByName(\"Ticket\") | matchValue(c2Fg)"
          }
        }
      },
      "dataSources": {
        "primary": "ds_029"
      },
      "title": "Change log — with the impact that followed",
      "context": {
        "c0Bg": [
          {
            "match": "Outage 57 min",
            "value": "#3F1D20"
          },
          {
            "match": "Outage 12 min",
            "value": "#3F1D20"
          },
          {
            "match": "Restored",
            "value": "#12301B"
          },
          {
            "match": "None",
            "value": "#1F242C"
          }
        ],
        "c0Fg": [
          {
            "match": "Outage 57 min",
            "value": "#FF8A80"
          },
          {
            "match": "Outage 12 min",
            "value": "#FF8A80"
          },
          {
            "match": "Restored",
            "value": "#56D364"
          },
          {
            "match": "None",
            "value": "#9AA4B2"
          }
        ],
        "c2Bg": [
          {
            "match": "none",
            "value": "#3A2E12"
          }
        ],
        "c2Fg": [
          {
            "match": "none",
            "value": "#E3B341"
          }
        ]
      }
    },
    "bg_030": {
      "type": "splunk.rectangle",
      "options": {
        "fillColor": "#161B22",
        "strokeColor": "#262C36",
        "strokeWidth": 1,
        "rx": 12
      }
    },
    "viz_031": {
      "type": "splunk.bar",
      "options": {
        "backgroundColor": "#161B22",
        "legendDisplay": "off",
        "xAxisTitleVisibility": "hide",
        "yAxisTitleVisibility": "hide",
        "seriesColors": [
          "#D95926"
        ],
        "dataValuesDisplay": "all"
      },
      "dataSources": {
        "primary": "ds_032"
      },
      "title": "Top blocked destinations after changes (24h)"
    },
    "bg_033": {
      "type": "splunk.rectangle",
      "options": {
        "fillColor": "#161B22",
        "strokeColor": "#262C36",
        "strokeWidth": 1,
        "rx": 12
      }
    },
    "md_034": {
      "type": "splunk.markdown",
      "options": {
        "markdown": "DATA SOURCES NEEDED IN SPLUNK",
        "fontColor": "#16A3B0",
        "fontSize": "custom",
        "customFontSize": 12
      }
    },
    "bg_035": {
      "type": "splunk.rectangle",
      "options": {
        "fillColor": "#1C2530",
        "strokeColor": "#2D3A48",
        "strokeWidth": 1,
        "rx": 17
      }
    },
    "md_036": {
      "type": "splunk.markdown",
      "options": {
        "markdown": "VMware NSX Manager (DFW)",
        "fontColor": "#E6EDF3",
        "fontSize": "custom",
        "customFontSize": 13
      }
    },
    "bg_037": {
      "type": "splunk.rectangle",
      "options": {
