        "markdown": "VMware vCenter events",
        "fontColor": "#E6EDF3",
        "fontSize": "custom",
        "customFontSize": 13
      }
    },
    "bg_039": {
      "type": "splunk.rectangle",
      "options": {
        "fillColor": "#1C2530",
        "strokeColor": "#2D3A48",
        "strokeWidth": 1,
        "rx": 17
      }
    },
    "md_040": {
      "type": "splunk.markdown",
      "options": {
        "markdown": "Application logs & health checks",
        "fontColor": "#E6EDF3",
        "fontSize": "custom",
        "customFontSize": 13
      }
    },
    "bg_041": {
