  "dataSources": {
    "ds_011": {
      "type": "ds.search",
      "name": "ds_011",
      "options": {
        "query": "| makeresults format=csv data=\"ago,n\n13,19\n12,21\n11,20\n10,24\n9,22\n8,18\n7,17\n6,19\n5,23\n4,26\n3,25\n2,22\n1,24\n0,23\"\n| eval _time=relative_time(now(), \"@d\") - ago*86400\n| sort 0 _time\n| table _time n",
        "queryParameters": {
          "earliest": "-15m",
          "latest": "now"
        }
      }
    },
    "ds_014": {
      "type": "ds.search",
      "name": "ds_014",
      "options": {
        "query": "| makeresults format=csv data=\"ago,n\n11,5\n10,6\n9,4\n8,7\n7,5\n6,6\n5,4\n4,3\n3,3\n2,2\n1,3\n0,2\"\n| eval _time=relative_time(now(), \"@d\") - ago*604800\n| sort 0 _time\n| table _time n",
        "queryParameters": {
          "earliest": "-15m",
          "latest": "now"
        }
      }
    },
    "ds_017": {
      "type": "ds.search",
      "name": "ds_017",
      "options": {
        "query": "| makeresults format=csv data=\"ago,n\n11,9\n10,8\n9,10\n8,7\n7,8\n6,6\n5,5\n4,4\n3,4\n2,3\n1,3\n0,2\"\n| eval _time=relative_time(now(), \"@d\") - ago*604800\n| sort 0 _time\n| table _time n",
        "queryParameters": {
          "earliest": "-15m",
          "latest": "now"
        }
      }
    },
    "ds_020": {
      "type": "ds.search",
      "name": "ds_020",
      "options": {
        "query": "| makeresults format=csv data=\"ago,m\n11,180\n10,150\n9,210\n8,160\n7,170\n6,14\n5,9\n4,7\n3,6\n2,6\n1,5\n0,6\"\n| eval _time=relative_time(now(), \"@d\") - ago*604800\n| sort 0 _time\n| table _time m",
        "queryParameters": {
          "earliest": "-15m",
          "latest": "now"
        }
      }
    },
    "ds_023": {
      "type": "ds.search",
      "name": "ds_023",
      "options": {
        "query": "| makeresults format=csv data=\"ago,Blocked connections\n71,7\n70,3\n69,6\n68,5\n67,3\n66,3\n65,4\n64,7\n63,6\n62,5\n61,5\n60,3\n59,5\n58,6\n57,4\n56,6\n55,7\n54,7\n53,3\n52,4\n51,7\n50,7\n49,5\n48,7\n47,3\n46,6\n45,5\n44,3\n43,5\n42,6\n41,5\n40,6\n39,3\n38,4\n37,5\n36,3\n35,3\n34,7\n33,4\n32,5\n31,6\n30,4\n29,415\n28,423\n27,414\n26,353\n25,396\n24,381\n23,427\n22,405\n21,388\n20,395\n19,425\n18,3\n17,3\n16,7\n15,7\n14,4\n13,3\n12,7\n11,5\n10,5\n9,4\n8,6\n7,6\n6,4\n5,4\n4,7\n3,4\n2,7\n1,3\n0,4\"\n| eval _time=relative_time(now(), \"@m\") - ago*300\n| sort 0 _time\n| table _time \"Blocked connections\"",
        "queryParameters": {
          "earliest": "-15m",
          "latest": "now"
        }
      }
    },
    "ds_026": {
      "type": "ds.search",
      "name": "ds_026",
      "options": {
        "query": "| makeresults format=csv data=\"Changed by,Changes\nExternal vendors,41\nNetwork team,27\nApplication teams,18\nAutomation (vRA),22\"\n| table \"Changed by\" Changes",
        "queryParameters": {
          "earliest": "-15m",
          "latest": "now"
        }
      }
    },
    "ds_029": {
      "type": "ds.search",
      "name": "ds_029",
      "options": {
        "query": "| makeresults format=csv data=\"When,Changed by,Object,Change,Ticket,Impact\n95,net-admin j.keller,Rule LIS-App-to-DB,Reverted to 1433,CHG0041877,Restored\n152,vendor-lis (ext.),Rule LIS-App-to-DB,Port 1433 → 14330,none,Outage 57 min\n410,app-pacs m.brunner,Group SG-PACS-Web,Added VM pacs-web-03,CHG0041862,None\n760,automation (vRA),Segment Seg-Lab-12,New segment + rules,CHG0041850,None\n1930,vendor-lis (ext.),Rule LIS-Interfaces,Source range narrowed,none,Outage 12 min\n2880,net-admin s.frei,Service HL7-MLLP,Added port 2575,CHG0041811,None\"\n| eval \"When\"=strftime(relative_time(now(), \"@m\") - 'When'*60, \"%a %H:%M\")\n| table When \"Changed by\" Object Change Ticket Impact",
        "queryParameters": {
          "earliest": "-15m",
          "latest": "now"
        }
      }
    },
    "ds_032": {
      "type": "ds.search",
      "name": "ds_032",
      "options": {
        "query": "| makeresults format=csv data=\"Destination,Blocked\nLIS DB :14330,4212\nHL7 engine :2575,388\nPACS DICOM :104,121\nAD (SMB) :445,64\"\n| table Destination Blocked",
        "queryParameters": {
          "earliest": "-15m",
          "latest": "now"
        }
      }
    }
  },
